def icon(name: str, size: int = 18, color: str = "currentColor", stroke_width: float = 1.85, extra_class: str = "") -> str:
    """Returns pure inline SVG for any Lucide icon."""
    path = ICONS_SVG.get(name, ICONS_SVG['sparkles'])
    cls_attr = f' class="lucide-icon {extra_class}"' if extra_class else ' class="lucide-icon"'
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" '
        f'fill="none" stroke="{color}" stroke-width="{stroke_width}" stroke-linecap="round" stroke-linejoin="round"'
        f'{cls_attr} style="vertical-align:middle;display:inline-block;flex-shrink:0;">'
        f'{path}'
        f'</svg>'
    )
